CREATE TABLE IF NOT EXISTS agent_updates (server_id varchar(36) PRIMARY KEY, request_id varchar(36) NOT NULL DEFAULT '', credential_hash varchar(64) NOT NULL DEFAULT '', status varchar(16) NOT NULL DEFAULT 'idle', target_version varchar(32) NOT NULL DEFAULT '', updater_seen_at datetime(6), expires_at datetime(6), message varchar(256) NOT NULL DEFAULT '', FOREIGN KEY(server_id) REFERENCES servers(id)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
